function sayZh(text,who,done){
  try{
    const ss=window.speechSynthesis;if(!ss){done&&setTimeout(done,600);return;}
    const u=new SpeechSynthesisUtterance(text.replace(/[“”]/g,''));u.lang='zh-CN';
    const g=VO[(CH[who]||{}).g]||{p:1.05};
    if(g.male&&window.hhMale){const m=hhMale();if(m)u._v=m;else u._p=.8;}
    u._p=u._p||g.p;u._r=SLOW?.6:(g.r||.85);
    let fin=false;const end=()=>{if(fin)return;fin=true;done&&done();};
    u.onend=end;u.onerror=end;setTimeout(end,1500+text.length*(SLOW?550:380));
    ss.speak(u);
  }catch(e){done&&done();}
}
